        long product = createProduct("한정판", 1000, 3);

        createOrder("[{\"productId\":%d,\"quantity\":3}]".formatted(product));

        assertThat(stockOf(product)).isZero();
    }

    @ParameterizedTest
    @ValueSource(strings = {
            "{}",                                                     // items 누락
