            "{\"items\":[null]}",                                     // null 항목
            "{\"items\":[{\"quantity\":1}]}",                         // productId 누락
            "{\"items\":[{\"productId\":1}]}",                        // quantity 누락
            "{\"items\":[{\"productId\":1,\"quantity\":0}]}",         // quantity < 1
            "{\"items\":[{\"productId\":1,\"quantity\":-3}]}",
